CREATE TABLE IF NOT EXISTS counters (k TEXT PRIMARY KEY, n INTEGER NOT NULL, reset INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cache (k TEXT PRIMARY KEY, body TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS robots (origin TEXT PRIMARY KEY, body TEXT NOT NULL, expires INTEGER NOT NULL, next_slot INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, scope TEXT NOT NULL, lim INTEGER NOT NULL, depth INTEGER NOT NULL, formats TEXT NOT NULL, self TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pages (job TEXT NOT NULL, url TEXT NOT NULL, depth INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'queued', data TEXT, PRIMARY KEY (job, url));
CREATE TABLE IF NOT EXISTS setups (id TEXT PRIMARY KEY, url TEXT NOT NULL, mode TEXT NOT NULL, fields TEXT NOT NULL, created INTEGER NOT NULL, last_run INTEGER NOT NULL);
